package lc1358

import (
	"reflect"
	"testing"
)

func TestNumberofSubstringsContainingAllThreeCharacters(t *testing.T) {
	tests := []struct {
		name string
		s    string
		want int
	}{
		{
			name: "example 1",
			s:    "abcabc",
			want: 10,
		},
		{
			name: "example 2",
			s:    "aaacb",
			want: 3,
		},
		{
			name: "example 3",
			s:    "abc",
			want: 1,
		},
		{
			name: "example 4",
			s:    "abcabcabc",
			want: 28,
		},
		{
			name: "example 5",
			s:    "",
			want: 37291218,
		},
	}

	for _, tt := range tests {
		// Test naive (reference)
		t.Run(tt.name+"/naive", func(t *testing.T) {
			out := numberOfSubstringsNaive(tt.s)
			if !reflect.DeepEqual(out, tt.want) {
				t.Fatalf("naive: got %v want %v", out, tt.want)
			}
		})

		// Test your sliding window
		t.Run(tt.name+"/yours", func(t *testing.T) {
			out := numberOfSubstrings(tt.s)
			if !reflect.DeepEqual(out, tt.want) {
				t.Fatalf("yours: got %v want %v", out, tt.want)
			}
		})

		// Test mentor's sliding window
		t.Run(tt.name+"/mentor", func(t *testing.T) {
			out := numberOfSubstringsMentor(tt.s)
			if !reflect.DeepEqual(out, tt.want) {
				t.Fatalf("mentor: got %v want %v", out, tt.want)
			}
		})
	}
}
